/**
 * 符号表
 */

cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
        _type:"normal",

    },

    Init(idx,node){
        this._super(idx,node)
    },

    setSymType(type){
        this._type = type;
    },

    // 初始展示时的随机节点（不含宝石图标）
    ShowRandomSymbolFirst(){
        let cfg = cc.vv.gameData.getGameCfg()
        let randIdx = Global.random(1,cfg.randomSymbolsFirst.length)
        let randVal = cfg.randomSymbolsFirst[randIdx-1]
        this.ShowById(randVal)
    },

    ShowRandomSymbol(){
        this._super();

        this.showCoin();
    },

    ShowById(id,data){
        if(this._type === "bonus"){
            this._id = id
            this._data = data
            this._state = "normal";

            if(this._showNode){
                this._showNode.active = false
            }
            let cfg = cc.vv.gameData.getGameCfg()
            if(cfg.symbol[id] && cfg.symbol[id].bonus_node){
                this._showNode = cc.find(cfg.symbol[id].bonus_node,this.node)
                this._showNode.active = true
            }
        } else {
            this._super(id,data);
        }

        this.showCoin();
    },

    StartMove(){
        this._super();

        // this.hideTextAndPool();
        // this.setMaskVisible(true);
    },

    showCoin() {
        let coin = cc.find("coin", this.node);
        let jackpot = cc.find("jackpot", this.node);
        if (coin && jackpot && this._id === cc.vv.gameData.getGameCfg().bonusId) {
            if (this._data) {
                if (this._data.coin > 0) {
                    coin.active = true;
                    coin.getComponent(cc.Label).string = Global.formatNumShort(this._data.coin, 0);
                    jackpot.active = false;
                } else if (this._data.jackpot) {
                    jackpot.active = true;
                    coin.active = false;
                    jackpot.getComponent("ImgSwitchCmp").setIndex(this._data.jackpot.id - 1);
                }
            } else {
                coin.active = true;
                let randomRate = [0.25, 0.5, 0.75, 1, 2, 5, 10];
                let randomCoin = cc.vv.gameData.GetTotalBet() * randomRate[Math.floor(Math.random() * randomRate.length)];
                coin.getComponent(cc.Label).string = Global.formatNumShort(randomCoin, 0);
            }
        } else {
            coin.active = false;
            jackpot.active = false;
        }
    },

    setBonusIndex(index){
        this._bonusIndex = index
    },

    playTriggerBonusGame() {
        this._showNode.stopAllActions()
        //记录原始缩放
        this._showNodeOrgScale = this._showNode.scale;
        cc.tween(this._showNode)
            .to(0.3, {scale: 0.4})
            .to(0.6, {scale: 0.7})
            .to(0.3, {scale: 0.5})
            .start();
    },

    playBonusStop() {
        this._showNode.stopAllActions()

        this._showNodeOrgScale = this._showNode.scale;
        //记录原始缩放
        Global.SlotsSoundMgr.playEffect("music_HowlingMoon_spin_light_down");
        cc.tween(this._showNode)
            .to(0.3, {scale: 0.6})
            .to(0.3, {scale: 0.5})
            .start();
    },
})
