cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {

    },

    RegisterMsg(){
        this._super();

        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameAction, this);
    },

    UnregisterMsg(){
        this._super();

        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameAction, false, this);
    },

    init(deskInfo,gameId,gameJackpot){

        // this._bonusInfo =  deskInfo.bonusGame.info
        // this._bonusRestNum =  deskInfo.bonusGame.num
        // this._bonusPoolList =  deskInfo.bonusGame.poolList
        //
        // this._freeWinCoin =  deskInfo.freeWinCoin

        this._super(deskInfo,gameId,gameJackpot);
    },

    OnRcvNetSpine:function(msg){

        // if(msg.code == 200) {
        //
        //     this._bonusInfo = msg.bonusGame.info
        //     this._bonusRestNum = msg.bonusGame.num
        //     this._bonusPoolList = msg.bonusGame.poolList
        //
        //     this._freeWinCoin = msg.freeWinCoin
        // }


        this._super(msg);
    },

    /**
     * 请求子游戏数据51
     * @param dt
     */
    reqSubGame(dt) {
        return new Promise(res=>{
            let req = {
                c:MsgId.SLOT_SUBGAME_DATA,
                gameid:this._gameId,
                data:dt
            };
            cc.vv.NetManager.send(req, true);

            this._subCallBack = res;
        });
    },

    onRcvSubGameAction(msg){
        if(this._subCallBack){
            this._subCallBack(msg);
            this._subCallBack = null;
        }
    },

    SetPopupScript(scp){
        this._popupScp = scp;
    },

    GetPopupScript(){
        return this._popupScp;
    },

    SetBonusScript(scp){
        this._bonusScp = scp;
    },

    GetBonusScript(){
        return this._bonusScp;
    },

    SetIsBonusGame(isBonus){
        this._isBonusGame = isBonus;
    },

    IsBonusGame(){
        return this._isBonusGame;
    },

    GetChangeNumBet(){
        return this._deskInfo.bonusGame.tri.bet;
    },

    GetBonusInfo(){
        return this._gameInfo.bonusInfo;
    },

    GetBonusGame() {
        return (this._gameInfo && this._gameInfo.bonusGame) ? this._gameInfo.bonusGame : this._deskInfo.bonusGame;
    },

    GetBonusState(){
        return this._deskInfo.bonusGame.state
    },

    GetBonusWinCoin(){
        return this._gameInfo.bonusGame.coin
    },

    GetBonusRestNum(){
        return this._deskInfo.bonusGame.restCnt;
    },

    GetBonusPool(){
        return this._bonusPoolList;
    },

    GetFreeWinCoin(){
        return this._freeWinCoin;
    },

    // update (dt) {},
});
