// Learn life-cycle callbacks:
//  - https://docs.cocos.com/creator/manual/en/scripting/life-cycle-callbacks.html

cc.Class({
    extends: cc.Component,

    properties: {
        _exitCallBack:null,

        _curTimes:3,   // 当前剩余次数
        _curUnlockNum:0,    // 当前解锁的宝石个数

        _shelterList:[],    // 横条遮罩
        _bonusPoolList:[],   // 奖池节点
        _subGameData: null,
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    Init(){
        this.initBonusNode();

        this._slotsScript = this._bonus_slots.addComponent("Change_BonusSlots");

        this.initBonusUI();
    },

    // 初始化节点
    initBonusNode(){

        this._bg_bonus = cc.find("safe_node/spr_bg_bonus", this.node);
        this._normal_slots = cc.find("safe_node/slots", this.node);
        this._bonus_slots = cc.find("safe_node/bonus_slots", this.node);
        this._node_bonus_pool = cc.find("safe_node/bonus_pool", this.node);

        this._topAniNode = cc.find("top_ani",this._bonus_slots);
        this._gemTopNode = cc.find("top_gem",this._bonus_slots);

        this._mask_frame = cc.find("mask_frame", this._bonus_slots);
        this._frame_top = cc.find("frame_top", this._bonus_slots);
        this._node_reels = cc.find("reels", this._bonus_slots);
        this._node_bonus_win = cc.find("node_bonus_win", this._bonus_slots);

        this._frame_bg = cc.find("bg", this._mask_frame);
        this._node_col = cc.find("node_col", this._mask_frame);
        this._node_row_left = cc.find("node_row_left", this._mask_frame);
        this._node_row_right = cc.find("node_row_right", this._mask_frame);

        this._spr_left = cc.find("spr_left", this._mask_frame);
        this._spr_right = cc.find("spr_right", this._mask_frame);

        this._spr_up = cc.find("spr_up", this._frame_top);

        this._node_tit = cc.find("node_tit", this._frame_top);

        this._shelterList.push(cc.find("shelter_1", this._frame_top));
        this._shelterList.push(cc.find("shelter_2", this._frame_top));
        this._shelterList.push(cc.find("shelter_3", this._frame_top));
        this._shelterList.push(cc.find("shelter_4", this._frame_top));

        this._bonusPoolList.push(cc.find("prizePool_MINI",this._node_bonus_pool));
        this._bonusPoolList.push(cc.find("prizePool_MINOR",this._node_bonus_pool));
        this._bonusPoolList.push(cc.find("prizePool_MAJOR",this._node_bonus_pool));
        this._bonusPoolList.push(cc.find("prizePool_GRAND",this._node_bonus_pool));
    },

    // 初始化节点状态
    initBonusUI(){
        this._bg_bonus.active = false;
        this._normal_slots.active = true;
        this._bonus_slots.active = false;

        this._frame_bg.getChildByName("spr").active = false;

        this.setLineState(this._node_col, false);
        this.setLineState(this._node_row_left, false);
        this.setLineState(this._node_row_right, false);

        this._spr_up.active = false;


        this._node_tit.active = false;
        this._node_reels.active = false;
        this._node_bonus_win.active = false;
        this._node_bonus_pool.active = false;
        cc.find("safe_node/LMSlots_PrizePool_1", this.node).active = true;

        for(let i = 0; i < this._shelterList.length; i++){
            this._shelterList[i].active = false;
        }
    },

    setLineState(parentNode, bShow){
        for (let i = 0; i < parentNode.childrenCount; i++){
            parentNode.children[i].active = bShow;
        }
    },

    // 触发
    async triBonusGame(success){
        this._exitCallBack = success;

        await this.playTriAnim();
    },

    // 触发动画
    playTriAnim(){
        return new Promise(async (sucess, failed)=> {
            // 1.初始大小显示
            cc.find("safe_node/change", this.node).active = false;
            this._bg_bonus.active = true;
            this._normal_slots.active = false;
            this._bonus_slots.active = true;

            this._frame_bg.y = -414;
            this._spr_left.y = -414;
            this._spr_right.y = -414;
            this._spr_up.active = true;
            this._spr_up.y = 0;

            cc.find("safe_node/LMSlots_PrizePool_1", this.node).active = false;
            this._node_bonus_pool.active = true;
            this.initPoolList();

            await cc.vv.gameData.awaitTime(0.5);

            Global.SlotsSoundMgr.playEffect("sound_HowlingMoon_reels_change");

            // 3.背景、左右框上长到指定位置
            let awaitT2 = 1.5;
            cc.tween(this._frame_bg).to(awaitT2, {position:cc.v2(0, 0)}).start();
            cc.tween(this._spr_left)
                .to(awaitT2, {position:cc.v2(this._spr_left.x, 0)})
                .call(()=>{
                    cc.find("effect", this._spr_left).active = false;
                })
                .start();
            cc.find("effect", this._spr_left).getComponent(cc.Animation).play();
            cc.tween(this._spr_right)
                .to(awaitT2, {position:cc.v2(this._spr_right.x, 0)})
                .call(()=>{
                    cc.find("effect", this._spr_right).active = false;
                })
                .start();
            cc.find("effect", this._spr_right).getComponent(cc.Animation).play();
            cc.tween(this._spr_up)
                .to(awaitT2, {y: 414})
                .start();
            await cc.vv.gameData.awaitTime(awaitT2);

            // 5.竖条隔断上长到顶部，底部从中间长到两头 （同时）
            let awaitT4 = 1.5;
            for(let i = 0; i < this._node_col.childrenCount; i++){
                let node = this._node_col.children[i];
                node.active = true;
                node.y = -414;

                node.getChildByName("effect").active = true;
                node.getChildByName("effect").getComponent(cc.Animation).play();

                cc.tween(node).to(awaitT4, {position:cc.v2(node.x,414)})
                    .call(()=>{
                        node.getChildByName("effect").active = false;
                    })
                    .start();
            }

            // 6.246行从左往右，1357行从右往左，左右两列长到顶（同时）
            let awaitT5 = 1.5;
            for(let i = 0; i < this._node_row_left.childrenCount; i++){
                let node = this._node_row_left.children[i];
                node.active = true;
                node.x = -333;

                node.getChildByName("effect").active = true;
                node.getChildByName("effect").getComponent(cc.Animation).play();

                cc.tween(node).to(awaitT5, {position:cc.v2(333,node.y)})
                    .call(()=>{
                        node.getChildByName("effect").active = false;
                    })
                    .start();
            }
            for(let i = 0; i < this._node_row_right.childrenCount; i++){
                let node = this._node_row_right.children[i];
                node.active = true;
                node.x = 333;
                node.getChildByName("effect").active = true;
                node.getChildByName("effect").getComponent(cc.Animation).play();
                cc.tween(node).to(awaitT5, {position:cc.v2(-333,node.y)})
                    .call(()=>{
                        node.getChildByName("effect").active = false;
                    })
                    .start();
            }


            await cc.vv.gameData.awaitTime(awaitT5);

            // 7.顶部从两侧到中间


            // 8.3spins 弹出，背景、所有reels显示
            let awaitT7 = 0.5;
            this._node_tit.active = true;
            this._node_tit.setScale(0);

            cc.tween(this._node_tit).to(awaitT7, {scale:1}, { easing: 'backOut'}).start()
            this._curTimes = 3;
            this.setTitleNum(this._curTimes);

            this._node_reels.active = true;
            this._slotsScript.Init();
            this._slotsScript.reconnectInitSymbol();

            await cc.vv.gameData.awaitTime(0.5);

            // 9.4个锁条从上往下依次出现
            let bonusUnlockList = cc.vv.gameData.GetBonusGame().unlockInfo;
            for (let i = 0; i < this._shelterList.length; i++){
                if(this._curUnlockNum < bonusUnlockList[i]){
                    Global.SlotsSoundMgr.playEffect("sound_HowlingMoon_showlock");
                    this._shelterList[i].active = true;
                    cc.find("lbl_num",this._shelterList[i]).getComponent(cc.Label).string = bonusUnlockList[i] - this._curUnlockNum;
                    await cc.vv.gameData.awaitTime(0.3);
                }
            }

            // 12.设置当前为bonus游戏，并开始旋转
            cc.vv.gameData.SetIsBonusGame(true);
            this.reqSpin();

            sucess();
        })
    },

    // 断线
    async enterBonusGame(success){
        this._exitCallBack = success;

        this.showEnterState();

        await cc.vv.gameData.awaitTime(2);

        cc.vv.gameData.SetIsBonusGame(true);
        this.reqSpin();
    },

    showEnterState(){
        // 显示所有节点状态
        this._bg_bonus.active = true;
        this._normal_slots.active = false;
        this._bonus_slots.active = true;
        this._spr_left.position = cc.v2(this._spr_left.x,0);
        this._spr_right.position = cc.v2( this._spr_right.x,0);
        this._spr_up.active = true;
        this._spr_up.opacity = 255;
        this._node_bonus_pool.active = true;
        cc.find("safe_node/LMSlots_PrizePool_1", this.node).active = false;
        this.initPoolList();

        for(let i = 0; i < this._node_col.childrenCount; i++){
            let node = this._node_col.children[i];
            node.active = true;
            node.y = 414;

            node.getChildByName("effect").active = false;
        }

        for(let i = 0; i < this._node_row_left.childrenCount; i++){
            let node = this._node_row_left.children[i];
            node.active = true;
            node.x = 333;

            node.getChildByName("effect").active = false;

        }
        for(let i = 0; i < this._node_row_right.childrenCount; i++){
            let node = this._node_row_right.children[i];
            node.active = true;
            node.x = -333;
            node.getChildByName("effect").active = false;

        }

        this._node_tit.active = true;

        this._curTimes = cc.vv.gameData.GetBonusGame().restCnt;
        this.setTitleNum(this._curTimes);

        this._node_reels.active = true;
        this._slotsScript.Init();
        this._slotsScript.reconnectInitSymbol();

        // 显示遮罩层状态
        let bonusUnlockList = cc.vv.gameData.GetBonusGame().unlockInfo;
        for (let i = 0; i < this._shelterList.length; i++){
            if(this._curUnlockNum < bonusUnlockList[i]){
                this._shelterList[i].active = true;
                cc.find("lbl_num",this._shelterList[i]).getComponent(cc.Label).string = bonusUnlockList[i] - this._curUnlockNum;
            } else {
                this._shelterList[i].active = false;
            }
        }
    },

    exitBonusGame(){
        this.initBonusUI();
        cc.find("safe_node/change", this.node).active = true;
        cc.vv.gameData.SetIsBonusGame(false);
    },

    // 设置奖池节点
    initPoolList(){
        let bonusGame = cc.vv.gameData.GetBonusGame();
        for(let i = 0; i < this._bonusPoolList.length; i++){
            cc.find("lbl_num",this._bonusPoolList[i]).getComponent(cc.Label).string = Global.FormatNumToComma(bonusGame.jackpotValues[i]);
        }
    },

    // 设置标题次数
    setTitleNum(num){
        for (let i = 0; i < 3; i++) {
            let show = cc.find("spin_" + (i + 1) + "/show", this._node_tit);
            show.active = (num === (i + 1));
        }

        this._curTimes = num;
        if (num === 3) {
            Global.SlotsSoundMgr.playEffect("music_HowlingMoon_spin_respin_to3");
        }
    },


    //点击停止按钮调用
    StopMove:function(){
        this._slotsScript.StopMove();
    },

    //全部列都停止了
    //处理停下后的中奖情况，这里多数情况需要根据自己的逻辑来处理
    async OnSpinEnd(){

        // await cc.vv.gameData.awaitTime(2);

        let restNum = this._subGameData.restCnt;
        this.setTitleNum(restNum);

        await this.updateShelter();

        if(restNum === 0){
            Global.SlotsSoundMgr.playEffect("music_HowlingMoon_spin_respin_Over");
            await this.playCompleteAnim();

            await cc.vv.gameData.GetPopupScript().showBonusEnd(cc.vv.gameData.getDeskInfo().bonusGame.winCoin);

            cc.vv.gameData.GetSlotsScript().cutScene();

            await cc.vv.gameData.awaitTime(1.5);


            //4.切屏
            this.exitBonusGame();
            this._normal_slots.active = true;
            this._bonus_slots.active = false;

            cc.vv.gameData.AddCoin(cc.vv.gameData.getDeskInfo().bonusGame.winCoin);

            cc.vv.gameData.GetSlotsScript().ShowBottomWin(cc.vv.gameData.getDeskInfo().bonusGame.winCoin,
                cc.vv.gameData.getDeskInfo().bonusGame.winCoin, true, ()=>{
                    if(this._exitCallBack){
                        this._exitCallBack();
                    }
                    cc.vv.gameData.GetSlotsScript().CanDoNextRound();
            })



        } else {
            await cc.vv.gameData.awaitTime(1);

            this.reqSpin();
        }

    },

    // 隐藏遮罩条
    updateShelter(){
        return new Promise(async (sucess, failed)=> {
            let bonusGame = cc.vv.gameData.getDeskInfo().bonusGame;
            let preUnlockInfo = bonusGame.preUnlockInfo;
            let unlockInfo = bonusGame.unlockInfo;
            for (let i = 3; i >= 0; i--) {
                if (preUnlockInfo[i] !== unlockInfo[i]) {
                    if (unlockInfo[i] === 0) {
                        // 解锁一条
                        Global.SlotsSoundMgr.playEffect("sound_HowlingMoon_unlock");
                        let unlock = cc.find("unlock_" + (i + 1), this._frame_top);
                        unlock.active = true;
                        unlock.getComponent(cc.Animation).play();
                        unlock.getComponent(cc.Animation).on("stop", ()=>{
                            unlock.active = false;
                            this._shelterList[i].active = false;
                        });

                        await cc.vv.gameData.awaitTime(1);
                    } else {
                        for (let j = 0; j < 4; j++) {
                            let shelter = this._shelterList[j];
                            cc.find("lbl_num", shelter).getComponent(cc.Label).string =
                                preUnlockInfo[j] - (preUnlockInfo[j] - unlockInfo[j]);
                        }
                    }
                }
            }

            sucess();
        })
    },

    // 播放完成动画
    playCompleteAnim(){
        return new Promise(async (sucess, failed)=> {
            Global.SlotsSoundMgr.playEffect("music_HowlingMoon_spin_respin_RunOver");
            let bonusGame = cc.vv.gameData.getDeskInfo().bonusGame;
            for (let item of bonusGame.items) {
                let reel = this._slotsScript.getReel(item.idx - 1);
                let node = cc.instantiate(cc.vv.gameData.GetPrefabByName("symbol"));
                node.parent = cc.find("top_ani", this._bonus_slots);
                node.addComponent("Change_Symbol");
                let position = reel.node.convertToWorldSpaceAR(cc.v2(0, 0));
                position = cc.find("top_ani", this._bonus_slots).convertToNodeSpaceAR(position);
                node.position = position;
                node.getComponent("Change_Symbol").ShowById(cc.vv.gameData.getGameCfg().bonusId, item);

                cc.tween(node)
                    .to(0.5, {scale: 1.1})
                    .to(0.5, {scale: 1})
                    .removeSelf()
                    .start();
            }

            await cc.vv.gameData.awaitTime(1);

            this._node_bonus_win.active = true;
            cc.find("lbl_win", this._node_bonus_win).getComponent(cc.Label).string = "";

            bonusGame.items.sort((a, b)=>{
                return a.idx - b.idx;
            });

            let bonus_bao = cc.find("safe_node/bonus_bao", this.node);
            let winCoin = 0;
            for (let i = 0; i < bonusGame.items.length; i++) {
                let unlockInfo = bonusGame.unlockInfo;
                let item = bonusGame.items[i];
                if (item.idx <= 20) {
                    if (unlockInfo[Math.floor((item.idx - 1) / 5)] !== 0) {
                        continue;
                    }
                }

                Global.SlotsSoundMgr.playEffect("music_HowlingMoon_spin_respin_RunOver");
                let bao = cc.instantiate(bonus_bao);
                bao.active = true;
                bao.parent = this.node.parent;
                let position = this._slotsScript.getReel(item.idx - 1).node.convertToWorldSpaceAR(cc.v2(0, 0));
                position = this.node.parent.convertToNodeSpaceAR(position);
                bao.position = position;
                bao.getComponent(cc.Animation).play();
                bao.getComponent(cc.Animation).on("stop", ()=>{
                    bao.removeFromParent();
                });

                winCoin += item.jackpot ? item.jackpot.value : item.coin;
                cc.find("lbl_win", this._node_bonus_win).getComponent(cc.Label).string = Global.FormatNumToComma(winCoin);
                for (let j = 0; j < 3; j++) {
                    let animation = cc.find("animation_" + (j + 1), this._node_bonus_win);
                    animation.active = true;
                    animation.getComponent(cc.Animation).play();
                }

                if (item.jackpot) {
                    await cc.vv.gameData.GetPopupScript().showJackpot(item.jackpot);
                }

                await cc.vv.gameData.awaitTime(0.5);
            }

            for (let j = 0; j < 3; j++) {
                let animation = cc.find("animation_" + (j + 1), this._node_bonus_win);
                animation.active = false;
            }

            sucess()
        })
    },

    //返回51请求结果
    getSubGameData(){
        return this._subGameData;
    },

    getMaxReelIdx(type, col){
        let reelList = this._slotsScript.getLastStopReel();
        return reelList[col];
    },

    // 获取最后停止的列和卷轴
    GetLastStopSlotReel(){
        return this._slotsScript.GetLastStopReelIdx();
    },


    // 发送下一次旋转请求
    async reqSpin(){
        this._subGameData = null;
        this._curTimes--;
        this.setTitleNum(this._curTimes);
        this._slotsScript.StartMove(cc.vv.gameData.getDeskInfo().bonusGame.items);
        let reqdata = {rtype:1};
        let result = await cc.vv.gameData.reqSubGame(reqdata);
        if(result.code === 200 && !result.spcode){
            this._subGameData = result.data.bonusGame;
            cc.vv.gameData.getDeskInfo().bonusGame = result.data.bonusGame;
            // cc.vv.gameData.setBonusGame(this._subGameData);

            this._slotsScript.setSpinResult(result.data.bonusGame);
        }
    },
});
