cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
        _isFiveGem: false,   // 当前为5个宝石触发bonus
        _isFreeGame: false,
    },

    start() {

    },

    Init(top, bottom) {
        this._node_banner = cc.find("node_banner", this.node);

        this._super(top, bottom);

        this.onEventTotalbetUpdated();

        cc.find("node_free/total", this.node).getComponent(cc.Label).string = 10;
        cc.find("node_free/times", this.node).getComponent(cc.Label).string =
            10;
    },

    RegisterEvent: function () {
        this._super();

        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED, this.onEventTotalbetUpdated, this)// 押注额改变
    },

    // 断线重连
    async ReconnectShow() {
        // this._super();

        let deskInfo = cc.vv.gameData.getDeskInfo();
        this.onEventTotalbetUpdated();

        if (deskInfo.bonusGame) {
            await new Promise(async (sucess, failed) => {
                cc.vv.gameData.GetBonusScript().enterBonusGame(sucess);
            })
        }

        if (cc.vv.gameData.GetTotalFree() > 0) {
            this.ShowGameview(true);
        } else {
            this.ShowGameview(false);
        }
        //   退出免费之类的
        this.CanDoNextRound();
    },

    onMsgSpine(msg) {
        if (cc.vv.gameData.IsBonusGame()) {
            cc.vv.gameData.GetBonusScript().onMsgSpine(msg)
        } else {
            this._super(msg);
        }
    },

    SetSlotsResult: function (cards) {
        //把结果按卷轴结果整理
        let acRow = cards.length / this._col;
        let reelResults = [];
        for (let i = 0; i < cards.length; i++) {
            let row = Math.floor(i / acRow);
            let col = i % this._col;
            //配置中有没有这个元素
            if (this._cfg.symbol[cards[i]]) {
                let res = {};
                res.sid = cards[i]; //符号id
                if (cards[i] === this._cfg.bonusId) {
                    for (let item of this._gameInfo.bonusInfo.items) {
                        if (item.idx === (i + 1)) {
                            res.data = item;
                            break;
                        }
                    }
                }
                if (!reelResults[col]) reelResults[col] = [];
                reelResults[col].unshift(res);
            }
        }

        for (let i = 0; i < this._reels.length; i++) {
            let item = this._reels[i]
            let reelRes = reelResults[i]
            item.SetResult(reelRes)
        }
    },

    StartMove() {
        if (cc.vv.gameData.IsBonusGame()) {
            return;
        }

        this._super();
        Global.SlotsSoundMgr.playNormalBgm()

        if (this._isFreeGame) {
            cc.find("node_free/total", this.node).getComponent(cc.Label).string = cc.vv.gameData.GetTotalFree();
            cc.find("node_free/times", this.node).getComponent(cc.Label).string =
                cc.vv.gameData.GetTotalFree() - cc.vv.gameData.GetFreeTime();
        }
    },

    StopMove() {
        if (cc.vv.gameData.IsBonusGame()) {
            cc.vv.gameData.GetBonusScript().StopMove();
        } else {
            this._super();
        }
    },

    async OnSpinEnd() {

        await this.checkExtraFreeGame();

        // 显示中奖路线
        this.ShowWinTrace()
        // 显示底部赢钱
        let nWin = cc.vv.gameData.GetGameWin()
        let nTotal = nWin
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() !== cc.vv.gameData.GetFreeTime()) {
            nTotal = cc.vv.gameData.GetGameTotalFreeWin()
        }

        this.ShowBottomWin(nWin, nTotal, true, async () => {
            if (this._gameInfo.bonusGame) {
                this.CheckTriggerBonusGame();
            } else if (this.CheckEnterFreeGame()) {
                this.triggerFreeGame();
            } else {
                if (this.CheckExitFreeGame()) {
                    this.triggerExitFreeGame();
                } else {
                    this.CanDoNextRound();
                }
            }
        });

    },

    async checkExtraFreeGame() {
        let spin = 0;
        for (let i = 0; i < this._gameInfo.resultCards.length; i++) {
            let card = this._gameInfo.resultCards[i];
            let symbol = this.GetSymbolByIdx(i + 1);
            if (card === this._cfg.extraFreeId) {
                spin++;
                symbol.playWinAnimation();
            }
        }

        if (spin > 0) {
            await cc.vv.gameData.awaitTime(1);

            Global.SlotsSoundMgr.playEffect("music_HowlingMoon_show_view");

            let trigger_extra_free = cc.find("trigger_extra_free", this.node);
            let moon = cc.find("moon", trigger_extra_free);
            let title = cc.find("title", trigger_extra_free);
            title.getComponent("ImgSwitchCmp").setIndex(spin > 1 ? 1 : 0);

            let times = cc.find("times", trigger_extra_free);
            times.getComponent(cc.Label).string = "+" + spin;

            trigger_extra_free.active = true;
            moon.opacity = 0;
            moon.scale = 0;
            cc.tween(moon)
                .to(0.5, {scale: 1.5, opacity: 255}, {easing: "backOut"})
                .start();

            title.opacity = 0;
            title.scale = 0;
            cc.tween(title)
                .to(0.5, {scale: 1, opacity: 255}, {easing: "backOut"})
                .start();

            times.scale = 0;
            cc.tween(times)
                .delay(0.3)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();

            await cc.vv.gameData.awaitTime(1.5);

            cc.tween(moon)
                .to(0.5, {scale: 0, opacity: 0}, {easing: "backIn"})
                .call(()=>{
                    trigger_extra_free.active = false;
                })
                .start()

            cc.tween(title)
                .to(0.5, {scale: 0, opacity: 0}, {easing: "backIn"})
                .start()

            cc.tween(times)
                .to(0.5, {scale: 0}, {easing: "backIn"})
                .start()
        }

    },

    // 检查触发免费
    CheckEnterFreeGame() {
        return cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetFreeTime() === cc.vv.gameData.GetTotalFree();
    },

    async triggerFreeGame() {
        Global.SlotsSoundMgr.playEffect("HowlingMoon_trigger_fs");
        for (let i = 0; i < this._gameInfo.resultCards.length; i++) {
            let card = this._gameInfo.resultCards[i];
            if (card === this._cfg.scatterId) {
                let symbol = this.GetSymbolByIdx(i + 1);
                if (symbol) {
                    symbol.playWinAnimation();
                }
            }
        }

        await cc.vv.gameData.awaitTime(1.5);

        this.Backup();

        await cc.vv.gameData.GetPopupScript().showFirstGainFree();

        await cc.vv.gameData.awaitTime(0.8);
        this.ShowGameview(true)

        Global.SlotsSoundMgr.stopBgm();
        Global.SlotsSoundMgr.playBgm("sound_HowlingMoon_freespin_bg");

        this.CanDoNextRound();
    },

    // 免费结束
    CheckExitFreeGame() {
        return cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetFreeTime() === 0;
    },

    async triggerExitFreeGame() {
        await cc.vv.gameData.GetPopupScript().showEndFree(cc.vv.gameData.GetGameTotalFreeWin());

        await cc.vv.gameData.awaitTime(0.8);

        this.Resume();
        this.ShowGameview(false);

        await cc.vv.gameData.awaitTime(0.5);
        let nWin = cc.vv.gameData.GetGameTotalFreeWin();
        let nTotal = nWin;

        this.ShowBottomWin(nWin, nTotal, true, () => {
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playNormalBgm()

            this.CanDoNextRound();
        })
    },

    // 触发小游戏
    async CheckTriggerBonusGame() {
        return new Promise(async (sucess, failed) => {
            Global.SlotsSoundMgr.playEffect("music_HowlingMoon_enter_bonus");

            cc.vv.gameData.getDeskInfo().bonusGame = this._gameInfo.bonusGame;

            for (let item of this._gameInfo.bonusGame.items) {
                let symbol = this.GetSymbolByIdx(item.idx);
                if (symbol) {
                    symbol.playTriggerBonusGame();
                }
            }

            await cc.vv.gameData.awaitTime(2);

            Global.SlotsSoundMgr.playEffect("music_HowlingMoon_show_view");
            let trigger_bonus = cc.find("trigger_bonus", this.node);
            let moon = cc.find("moon", trigger_bonus);
            let title = cc.find("title", trigger_bonus);
            trigger_bonus.active = true;
            moon.opacity = 0;
            moon.scale = 0;
            cc.tween(moon)
                .to(0.5, {scale: 1.5, opacity: 255}, {easing: "backOut"})
                .start();

            title.opacity = 0;
            title.scale = 0;
            cc.tween(title)
                .delay(0.1)
                .to(0.5, {scale: 1, opacity: 255}, {easing: "backOut"})
                .start();

            await cc.vv.gameData.awaitTime(1.5);

            cc.tween(moon)
                .to(0.5, {scale: 0, opacity: 0}, {easing: "backIn"})
                .call(()=>{
                    trigger_bonus.active = false;
                })
                .start()

            cc.tween(title)
                .to(0.5, {scale: 0, opacity: 0}, {easing: "backIn"})
                .start()

            await cc.vv.gameData.awaitTime(0.5);

            this.cutScene();
            await cc.vv.gameData.awaitTime(1.5);
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playBgm("music_HowlingMoon_linghtning_frame");
            cc.vv.gameData.GetBonusScript().triBonusGame(sucess)
        })
    },

    cutScene() {
        Global.SlotsSoundMgr.playEffect("music_HowlingMoon_spin_transition");
        let transition = cc.find("transition", this.node.parent);
        transition.active = true;
        transition.getComponent(sp.Skeleton).setAnimation(0, "skill", false);
        transition.getComponent(sp.Skeleton).setCompleteListener(()=>{
            transition.getComponent(sp.Skeleton).setCompleteListener(null);
            transition.active = false;
        });
    },

    //显示游戏界面：bFree true显示免费模式的界面，false 普通模式
    ShowGameview: function (bFree) {
        this._isFreeGame = bFree;
        let node_free = cc.find("node_free", this.node);
        node_free.active = bFree;
        this._node_banner.active = !bFree;
        if (bFree) {
            Global.SlotsSoundMgr.playBgm('free_bgm')

            let total = cc.vv.gameData.GetTotalFree()
            let rest = cc.vv.gameData.GetFreeTime()

            //显示免费次数
            this._bottomScript.ShowFreeModel(true, total - rest, total)
            let nTotal = cc.vv.gameData.GetFreeWinCoin()
            this._bottomScript.SetWin(nTotal)

            cc.find("total", node_free).getComponent(cc.Label).string = total;
            cc.find("times", node_free).getComponent(cc.Label).string = (total - rest);

        } else {
            this._bottomScript.ShowFreeModel(false)
        }



    },

    // 押注额改变
    onEventTotalbetUpdated() {
        let node_4 = cc.find("node_4", this._node_banner);
        let node_5 = cc.find("node_5", this._node_banner);

        let curBet = cc.vv.gameData.GetBetIdx();
        let minBet = cc.vv.gameData.getDeskInfo().needBet;

        if (!this._isFiveGem && curBet < minBet) {
            Global.SlotsSoundMgr.playEffect("sound_HowlingMoon_unlock_highbet");
            this._isFiveGem = true
            node_4.active = false;
            node_5.active = true;
        } else if (this._isFiveGem && curBet >= minBet) {
            Global.SlotsSoundMgr.playEffect("sound_HowlingMoon_unlock_highbet");
            this._isFiveGem = false
            node_4.active = true;
            node_5.active = false;
        }
    },
    /*
        GetBonusData(idx){
            let infoData = cc.vv.gameData.GetBonusInfo();
            return infoData[idx];
        },*/
});
