cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    Init(){
        this._node_popup =  cc.find("safe_node/node_popup", this.node);
        this._node_popup.active = false;

        this._node_free_start = cc.find("pop_free_start",this._node_popup);
        this._node_free_end = cc.find("pop_free_end",this._node_popup);
        this._node_bonus_end = cc.find("pop_bonus_end", this._node_popup);
        this._node_jackpot = cc.find("pop_jackpot", this._node_popup);

        this._node_free_start.active = false;

        this._node_free_end.active = false;
        this._node_bonus_end.active = false;
        this._node_jackpot.active = false;

    },

    // 首次获得免费游戏
    async showFirstGainFree(){
        return new Promise(async (sucess, failed)=>{
            this._node_popup.active = true;
            this._node_free_start.active = true;

            Global.SlotsSoundMgr.playEffect("music_HowlingMoon_show_view");
            this._node_free_start.setScale(0);
            cc.tween(this._node_free_start).to(0.7,{scale:1}, {easing:"backOut"}).start();

            cc.find("times", this._node_free_start).getComponent(cc.Label).string = cc.vv.gameData.GetTotalFree();

            let btn_start = this._node_free_start.getChildByName("btn_start");
            await cc.vv.gameData.awaitTime(0.5);
            btn_start.getComponent(cc.Button).interactable = true;
            btn_start.off("click");
            let self = this;
            btn_start.on("click", ()=>{
                // Global.SlotsSoundMgr.playEffect("free_dialog_collect_click");
                btn_start.getComponent(cc.Button).interactable = false;
                cc.tween(this._node_free_start).to(0.7,{scale:0}, {easing:"backIn"})
                    .call(()=>{
                        self._node_popup.active = false;
                        self._node_free_start.active = false;
                        sucess();
                    })
                    .start();
            })
        });
    },

    // 免费结束
    showEndFree(winCoin){
        return new Promise(async (sucess, failed)=> {
            cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1");

            this._node_popup.active = true;
            this._node_free_end.active = true;

            Global.SlotsSoundMgr.playEffect("music_HowlingMoon_show_view");

            let lbl_winCoin = cc.find("win_bg/lbl_winCoin",this._node_free_end);
            Global.doRoallNumEff(lbl_winCoin,0,winCoin, 2,null,null,0,true);

            cc.find("times", this._node_free_end).getComponent(cc.Label).string = cc.vv.gameData.GetTotalFree();
            // Global.SlotsSoundMgr.playEffect("win_rollup");

            this._node_free_end.setScale(0);
            cc.tween(this._node_free_end).to(0.7,{scale:1}, {easing:"backOut"}).start();

            let btn_collect = this._node_free_end.getChildByName("btn_collect");
            await cc.vv.gameData.awaitTime(0.5);
            btn_collect.getComponent(cc.Button).interactable = true;
            btn_collect.off("click");
            let self = this;
            btn_collect.on("click", ()=>{
                Global.SlotsSoundMgr.playEffect("music_HowlingMoon_touch_view_btn");
                btn_collect.getComponent(cc.Button).interactable = false;
                cc.tween(this._node_free_end).to(0.7,{scale:0}, {easing:"backIn"})
                    .call(()=>{
                        self._node_popup.active = false;
                        self._node_free_end.active = false;
                        sucess();
                    })
                    .start();
            })

        });
    },

    showBonusEnd(winCoin){
        return new Promise(async (sucess, failed)=> {
            cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1");

            this._node_popup.active = true;
            this._node_bonus_end.active = true;

            let lbl_winCoin = cc.find("win_bg/lbl_winCoin",this._node_bonus_end);
            Global.doRoallNumEff(lbl_winCoin,0,winCoin, 2,null,null,0,true);

            // Global.SlotsSoundMgr.playEffect("win_rollup");

            Global.SlotsSoundMgr.playEffect("music_HowlingMoon_show_JackPOt_view");
            this._node_bonus_end.setScale(0);
            cc.tween(this._node_bonus_end).to(0.7,{scale:1}, {easing:"backOut"}).start();

            let btn_collect = this._node_bonus_end.getChildByName("btn_collect");
            await cc.vv.gameData.awaitTime(0.5);
            btn_collect.getComponent(cc.Button).interactable = true;
            btn_collect.off("click");
            let self = this;
            btn_collect.on("click", ()=>{
                Global.SlotsSoundMgr.playEffect("music_HowlingMoon_touch_view_btn");
                btn_collect.getComponent(cc.Button).interactable = false;
                cc.tween(this._node_bonus_end).to(0.7,{scale:0}, {easing:"backIn"})
                    .call(()=>{
                        self._node_popup.active = false;
                        self._node_bonus_end.active = false;
                        sucess();
                    })
                    .start();
            })

        });
    },

    async showJackpot(jackpot){
        return new Promise(async (sucess, failed)=> {
            cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1");

            this._node_popup.active = true;
            this._node_jackpot.active = true;

            let lbl_winCoin = cc.find("win_bg/lbl_winCoin",this._node_jackpot);
            lbl_winCoin.getComponent(cc.Label).string = Global.FormatNumToComma(jackpot.value);

            let jackpotImg = cc.find("jackpot", this._node_jackpot);
            jackpotImg.getComponent("ImgSwitchCmp").setIndex(jackpot.id - 1);

            // Global.SlotsSoundMgr.playEffect("win_rollup");

            Global.SlotsSoundMgr.playEffect("music_HowlingMoon_show_view");
            this._node_jackpot.setScale(0);
            cc.tween(this._node_jackpot).to(0.7,{scale:1}, {easing:"backOut"}).start();

            let btn_collect = this._node_jackpot.getChildByName("btn_collect");
            await cc.vv.gameData.awaitTime(0.5);
            btn_collect.getComponent(cc.Button).interactable = true;
            btn_collect.off("click");
            let self = this;
            btn_collect.on("click", ()=>{
                Global.SlotsSoundMgr.playEffect("music_HowlingMoon_touch_view_btn");
                btn_collect.getComponent(cc.Button).interactable = false;
                cc.tween(this._node_jackpot).to(0.7,{scale:0}, {easing:"backIn"})
                    .call(()=>{
                        self._node_popup.active = false;
                        self._node_jackpot.active = false;
                        sucess();
                    })
                    .start();
            })

        });
    },
});
